432	// nodeIP returns the first InternalIP any node reports, or "" when none does.
433	func (pf preflight) nodeIP(ctx context.Context) (string, error) {
434		args := []string{"get", "nodes", "-o", "json"}
435		out, errOut, err := pf.remote(ctx, args...)
436		if err != nil {
437			return "", pf.failure("read the nodes", args, errOut, err)
438		}
439		var nodes nodeList
440		if err := json.Unmarshal([]byte(out), &nodes); err != nil {
441			return "", &BenchError{
442				Kind:  Unclassified,
443				Cause: "kubectl answered with something that is not a Node list",
444				Check: pf.command(args...),
445				Err:   err,
446			}
447		}
448		for _, node := range nodes.Items {
449			for _, addr := range node.Status.Addresses {
450				if addr.Type == "InternalIP" {
451					return addr.Address, nil
452				}
453			}
454		}
455		return "", nil
456	}
