1	package nexusbench
2	
3	import (
4		"context"
5		"fmt"
6		"io"
7		"slices"
8		"strings"
9		"time"
10	)
11	
12	// upstreamPollInterval separates two rounds of the wait for the upstream. It is
13	// shorter than pollInterval: a registry is ready within seconds of its image
14	// being local, and the wait has no host to probe.
15	const upstreamPollInterval = 2 * time.Second
16	
17	// UpstreamState is what the cluster says about the bench upstream registry.
18	type UpstreamState int
19	
20	// The states of the upstream, from the least to the most alive.
21	const (
22		// UpstreamMissing: the Deployment bench-upstream does not exist.
23		UpstreamMissing UpstreamState = iota
24		// UpstreamCut: the Deployment exists with zero replicas.
25		UpstreamCut
26		// UpstreamStarting: one replica is wanted and no pod of it is ready yet.
27		UpstreamStarting
28		// UpstreamReady: a pod of the upstream that is not terminating is ready.
29		UpstreamReady
30	)
31	
32	// ReadUpstream reads the state of the bench upstream with read-only kubectl
33	// calls: it writes nothing and waits for nothing. A pod that fails to pull is
34	// Starting, not an error: diagnosing is the job of the wait. It runs no
35	// preflight; the caller does. Every failure is a *BenchError, but a cancelled
36	// context, which is returned as is.
37	func ReadUpstream(ctx context.Context, r Runner, p Params) (UpstreamState, error) {
38		d := &deployer{pf: preflight{r: r, p: p}, w: upstreamWorkload(), tag: "upstream", out: io.Discard}
39		return d.readUpstream(ctx)
40	}
41	
42	// EnsureUpstream brings the bench upstream to one ready replica, and returns
43	// when it is ready or fails with a diagnosis. It reads first and writes only
44	// when the upstream is cut: one scale to one replica, then the wait. A starting
45	// upstream is waited for without a write; a ready one is left alone. The
46	// Deployment itself is applied by Deploy, so a missing one is an error. A
47	// custom upstream (Params.UpstreamIsBench is false) is refused before any call:
48	// the bench scales what it deploys and nothing else. The wait polls the pods
49	// and the claim of the upstream only, until Params.Timeout. It runs no
50	// preflight; the caller does. Every failure is a *BenchError, but a cancelled
51	// context, which is returned as is. A nil out discards the progress lines.
52	func EnsureUpstream(ctx context.Context, r Runner, clk Clock, p Params, out io.Writer) error {
53		if out == nil {
54			out = io.Discard
55		}
56		if !p.UpstreamIsBench() {
57			return customUpstreamError(p)
58		}
59		// The runner of a test may ignore ctx; the first call must not depend on it.
60		if err := ctx.Err(); err != nil {
61			return err
62		}
63		d := &deployer{pf: preflight{r: r, p: p}, w: upstreamWorkload(), tag: "upstream", clk: clk, out: out}
64		state, err := d.readUpstream(ctx)
65		if err != nil {
66			return err
67		}
68		switch state {
69		case UpstreamMissing:
70			return missingUpstreamError(d)
71		case UpstreamReady:
72			d.say("the upstream is ready")
73			return nil
74		case UpstreamCut:
75			d.say("scaling the upstream to one replica")
76			if err := d.scaleUpstream(ctx, 1); err != nil {
77				return err
78			}
79		case UpstreamStarting:
80			d.say("the upstream is starting")
81		}
82		return d.waitUpstream(ctx)
83	}
84	
85	// missingUpstreamError is the error of an upstream that Deploy never applied.
86	func missingUpstreamError(d *deployer) *BenchError {
87		p := d.pf.p
88		return &BenchError{
89			Kind:  Unclassified,
90			Cause: fmt.Sprintf("the Deployment %s does not exist in namespace %q", upstreamDeployment, p.Namespace),
91			Check: "run `mise run nexus-bench:up`, which applies it, or " + d.pf.command("get", "deployment", upstreamDeployment, "-n", p.Namespace),
92		}
93	}
94	
95	// CutUpstream scales the bench upstream to zero replicas and returns once no
96	// pod of it is left, a terminating one included: its volume is still mounted
97	// until it is gone. It reads first and writes only when the upstream is not
98	// already cut: one scale to zero, never retried. An upstream that is cut is
99	// still waited for, as a pod of an earlier cut may be terminating. Like
100	// EnsureUpstream, it refuses a custom upstream before any call, treats a
101	// missing Deployment as an error, runs no preflight, returns a cancelled
102	// context as is and accepts a nil out. The wait lasts until Params.Timeout.
103	func CutUpstream(ctx context.Context, r Runner, clk Clock, p Params, out io.Writer) error {
104		if out == nil {
105			out = io.Discard
106		}
107		if !p.UpstreamIsBench() {
108			return customUpstreamError(p)
109		}
110		if err := ctx.Err(); err != nil {
111			return err
112		}
113		d := &deployer{pf: preflight{r: r, p: p}, w: upstreamWorkload(), tag: "upstream", clk: clk, out: out}
114		state, err := d.readUpstream(ctx)
115		if err != nil {
116			return err
117		}
118		switch state {
119		case UpstreamMissing:
120			return missingUpstreamError(d)
121		case UpstreamCut:
122			d.say("the upstream is already cut")
123		default:
124			d.say("scaling the upstream to zero replicas")
125			if err := d.scaleUpstream(ctx, 0); err != nil {
126				return err
127			}
128		}
129		return d.waitUpstreamGone(ctx)
130	}
131	
132	// customUpstreamError refuses an upstream the bench does not deploy.
133	func customUpstreamError(p Params) *BenchError {
134		return &BenchError{
135			Kind: Unclassified,
136			Cause: fmt.Sprintf("%s points at an upstream the bench did not deploy in namespace %q, and the bench scales only its own upstream",
137				envUpstreamURL, p.Namespace),
138			Check: "unset " + envUpstreamURL + " to use the bench upstream, or start and stop your own upstream registry yourself",
139		}
140	}
141	
142	// readUpstream is ReadUpstream on a deployer.
143	func (d *deployer) readUpstream(ctx context.Context) (UpstreamState, error) {
144		var dep struct {
145			Spec struct {
146				Replicas *int `json:"replicas"`
147			} `json:"spec"`
148		}
149		args := []string{"get", "deployment", upstreamDeployment, "-n", d.pf.p.Namespace, "-o", "json"}
150		found, err := d.fetch(ctx, "read the Deployment "+upstreamDeployment, args, &dep, true)
151		if err != nil {
152			return UpstreamMissing, err
153		}
154		if !found {
155			return UpstreamMissing, nil
156		}
157		// The manifest leaves the count out, so the API server defaults it to one.
158		if dep.Spec.Replicas != nil && *dep.Spec.Replicas == 0 {
159			return UpstreamCut, nil
160		}
161		var pods struct {
162			Items []podObject `json:"items"`
163		}
164		if err := d.read(ctx, "read the "+d.w.name+" pod", d.podsArgs(), &pods); err != nil {
165			return UpstreamMissing, err
166		}
167		if slices.ContainsFunc(pods.Items, podObject.ready) {
168			return UpstreamReady, nil
169		}
170		return UpstreamStarting, nil
171	}
172	
173	// scaleUpstream is the one write of EnsureUpstream. A failed write is not
174	// retried: the scale is not what a second try would fix.
175	func (d *deployer) scaleUpstream(ctx context.Context, replicas int) error {
176		args := []string{"scale", "deployment/" + upstreamDeployment, fmt.Sprintf("--replicas=%d", replicas), "-n", d.pf.p.Namespace, applyTimeout}
177		_, errOut, err := d.pf.r.Run(ctx, nil, args...)
178		if err == nil {
179			return nil
180		}
181		if cerr := ctx.Err(); cerr != nil {
182			return cerr
183		}
184		return d.pf.failure("scale the Deployment "+upstreamDeployment, args, string(errOut), err)
185	}
186	
187	// waitUpstream polls until a pod of the upstream is ready, a diagnosis fails the
188	// run, or the deadline passes. Like the wait of Deploy, it looks at the deadline
189	// after a round, so the cluster is read once more at the very end.
190	func (d *deployer) waitUpstream(ctx context.Context) error {
191		deadline := d.clk.Now().Add(d.pf.p.Timeout)
192		for {
193			obs, err := d.round(ctx)
194			if err != nil {
195				return err
196			}
197			if err := ctx.Err(); err != nil {
198				return err
199			}
200			if slices.ContainsFunc(obs.pods, podObject.ready) {
201				d.say("the upstream is ready")
202				return nil
203			}
204			if !d.clk.Now().Before(deadline) {
205				return d.upstreamDeadline(obs)
206			}
207			if err := d.clk.Sleep(ctx, upstreamPollInterval); err != nil {
208				return err
209			}
210		}
211	}
212	
213	// waitUpstreamGone polls the pods of the upstream until none is left, a
214	// terminating one included, or the deadline passes. Like waitUpstream, it looks
215	// at the deadline after a round.
216	func (d *deployer) waitUpstreamGone(ctx context.Context) error {
217		deadline := d.clk.Now().Add(d.pf.p.Timeout)
218		for {
219			var pods struct {
220				Items []podObject `json:"items"`
221			}
222			if err := d.read(ctx, "read the "+d.w.name+" pod", d.podsArgs(), &pods); err != nil {
223				return err
224			}
225			if err := ctx.Err(); err != nil {
226				return err
227			}
228			if len(pods.Items) == 0 {
229				d.say("no pod of the upstream is left")
230				return nil
231			}
232			if !d.clk.Now().Before(deadline) {
233				p := d.pf.p
234				names := make([]string, 0, len(pods.Items))
235				for _, pod := range pods.Items {
236					names = append(names, pod.Metadata.Name)
237				}
238				return &BenchError{
239					Kind:  Deadline,
240					Cause: fmt.Sprintf("the upstream %s still has pods after %s: %s", upstreamDeployment, p.Timeout, strings.Join(names, ", ")),
241					Check: describePodCommand(p, d.w) + ", then raise " + envTimeout + " if the pod is only slow to terminate",
242				}
243			}
244			if err := d.clk.Sleep(ctx, upstreamPollInterval); err != nil {
245				return err
246			}
247		}
248	}
249	
250	// upstreamDeadline is the end of a wait that ran out of time. A pending reading
251	// that was still there says more than the deadline does.
252	func (d *deployer) upstreamDeadline(obs observation) error {
253		if d.candidate != nil {
254			return d.candidate
255		}
256		p := d.pf.p
257		return &BenchError{
258			Kind:  Deadline,
259			Cause: fmt.Sprintf("the upstream %s was not ready within %s; last state: %s", upstreamDeployment, p.Timeout, obs.describe()),
260			Check: describePodCommand(p, d.w) + ", then raise " + envTimeout + " if the image pull or the start is only slow",
261		}
262	}
263	
264	// ready reports whether the pod is not terminating and its Ready condition is
265	// True.
266	func (pod podObject) ready() bool {
267		if pod.Metadata.DeletionTimestamp != nil {
268			return false
269		}
270		for _, c := range pod.Status.Conditions {
271			if c.Type == "Ready" {
272				return c.Status == "True"
273			}
274		}
275		return false
276	}
