11	// Op is what a run of the bench is about to do; it decides which checks the
12	// preflight makes.
13	type Op int
14	
15	const (
16		OpUp Op = iota
17		OpProvision
18		OpDown
19		OpStatus
20		// OpSeed is appended after OpStatus: no earlier value moves.
21		OpSeed
22		// OpCut, OpRestore and OpReset follow OpSeed, in this order.
23		OpCut
24		OpRestore
25		OpReset
26	)
27	
28	// readsNode is true for the operations that return the node address: down and
29	// the ones that go through the loopback (seed, cut, restore, reset) do not.
30	func (op Op) readsNode() bool {
31		return op == OpUp || op == OpProvision || op == OpStatus
32	}
33	
34	// PreflightResult is what a successful preflight learned about the cluster.
35	type PreflightResult struct {
36		// NamespaceExists is true when the bench namespace is there.
37		NamespaceExists bool
38		// NamespaceOurs is true when it carries our managed-by label.
39		NamespaceOurs bool
40		// NodeIP is the InternalIP of the first node that reports one; empty when
41		// none does, which is not an error (the other hosts still work). It is not
42		// read for OpDown.
43		NodeIP string
44	}
45	
46	const (
47		// managedByLabel and managedByValue are the label 00-namespace.yaml.tmpl
48		// puts on the namespace; down deletes a namespace only when it carries it.
49		managedByLabel = "app.kubernetes.io/managed-by"
50		managedByValue = "devdesk-nexus-bench"
51	
52		// nexusServiceName is the Service 30-service.yaml.tmpl creates.
53		nexusServiceName = "nexus"
54	
55		// requestTimeout bounds every call that reaches the API server.
56		requestTimeout = "--request-timeout=10s"
57	)
58	
59	// permissionScope says where a can-i question applies.
60	type permissionScope int
61	
62	const (
63		scopeCluster   permissionScope = iota // no flag: cluster-scoped resources
64		scopeNamespace                        // -n <namespace>
65		scopeAll                              // -A
66	)
67	
68	// permission is one "kubectl auth can-i" question the preflight asks.
69	type permission struct {
70		verb, resource string
71		// subresource is asked as --subresource=<sub>: kubectl reads "pods/exec" as
72		// the object "exec" of the pods, not as the exec subresource.
73		subresource string
74		scope       permissionScope
75	}
76	
77	// name is the resource as a message shows it: "pods/exec".
78	func (perm permission) name() string {
79		if perm.subresource == "" {
80			return perm.resource
81		}
82		return perm.resource + "/" + perm.subresource
83	}
84	
85	// seedPermissions are the questions of seed, which restore asks too and reset
86	// asks first. Seed reads the Deployment and the pods of the upstream, scales it
87	// back when it is cut, and reaches it through a port-forward, which gets the
88	// Service, then the pod it picks, before it opens the tunnel. EnsureUpstream
89	// reads the claim on every turn of its wait, so the two claim questions come
90	// before the first write.
91	var seedPermissions = []permission{
92		{"get", "deployments", "", scopeNamespace},
93		{"list", "pods", "", scopeNamespace},
94		{"get", "pods", "", scopeNamespace},
95		{"get", "services", "", scopeNamespace},
96		{"get", "persistentvolumeclaims", "", scopeNamespace},
97		{"list", "persistentvolumeclaims", "", scopeNamespace},
98		{"create", "pods", "portforward", scopeNamespace},
99		{"patch", "deployments", "scale", scopeNamespace},
100	}
101	
102	// permissionsByOp is the list F2 of the plan: what each operation needs. An
103	// operation absent from the map (status) writes nothing and asks nothing.
104	var permissionsByOp = map[Op][]permission{
105		OpUp: {
106			{"create", "namespaces", "", scopeCluster},
107			{"create", "persistentvolumeclaims", "", scopeNamespace},
108			{"create", "services", "", scopeNamespace},
109			{"create", "deployments", "", scopeNamespace},
110			{"create", "pods", "exec", scopeNamespace},
111			{"list", "services", "", scopeAll},
112			// Server-side apply is a PATCH, also on a second run (the namespace
113			// included), and Deploy reads the pods and the claims of the namespace
114			// while it waits.
115			{"patch", "namespaces", "", scopeCluster},
116			{"patch", "deployments", "", scopeNamespace},
117			{"patch", "services", "", scopeNamespace},
118			{"patch", "persistentvolumeclaims", "", scopeNamespace},
119			{"get", "pods", "", scopeNamespace},
120			{"list", "pods", "", scopeNamespace},
121			{"get", "persistentvolumeclaims", "", scopeNamespace},
122			{"list", "persistentvolumeclaims", "", scopeNamespace},
123			// The upstream: EnsureUpstream scales it, and the seed that follows up
124			// reaches it through a port-forward, which reads the Service first. Asked
125			// last, so the fourteen above stay where they were.
126			{"patch", "deployments", "scale", scopeNamespace},
127			{"create", "pods", "portforward", scopeNamespace},
128			{"get", "services", "", scopeNamespace},
129		},
130		// Provision waits for the Deployment and reads the pods before it execs.
131		OpProvision: {
132			{"create", "pods", "exec", scopeNamespace},
133			{"get", "deployments", "", scopeNamespace},
134			{"list", "pods", "", scopeNamespace},
135		},
136		OpDown:    {{"delete", "namespaces", "", scopeCluster}},
137		OpSeed:    seedPermissions,
138		OpRestore: seedPermissions,
139		// Cut reads the upstream Deployment, waits until no pod is left and scales
140		// it to zero: no tunnel, no Service, no claim.
141		OpCut: {
142			{"get", "deployments", "", scopeNamespace},
143			{"list", "pods", "", scopeNamespace},
144			{"patch", "deployments", "scale", scopeNamespace},
145		},
146		// Reset recycles the claim: what restore asks, then the writes on the claim
147		// (a server-side apply of an absent claim needs create). It never execs: the
148		// admin password is not changed.
149		OpReset: slices.Concat(seedPermissions, []permission{
150			{"delete", "persistentvolumeclaims", "", scopeNamespace},
151			{"create", "persistentvolumeclaims", "", scopeNamespace},
152			{"patch", "persistentvolumeclaims", "", scopeNamespace},
153		}),
154	}
155	
156	// RunPreflight checks, with read-only kubectl calls, that op can go ahead, and
157	// returns what it learned. Nothing is written to the cluster, whatever the
158	// outcome: a failure here means no write was ever issued. The checks run in a
159	// fixed order and stop at the first failure, so nothing is asked of a cluster
160	// the context does not reach:
161	//
162	//  1. the parameters (no call at all)
163	//  2. the context is in the kubeconfig
164	//  3. the API server answers /readyz
165	//  4. the can-i questions of the operation
166	//  5. the namespace: absent, ours, or foreign
167	//  6. up only: no other Service holds one of our NodePorts
168	//  7. up, provision and status only (Op.readsNode): the InternalIP of the node
169	//
170	// Every failure is a *BenchError.
171	func RunPreflight(ctx context.Context, r Runner, p Params, op Op) (PreflightResult, error) {
172		var res PreflightResult
173		if err := p.Validate(); err != nil {
174			return res, err
175		}
176		pf := preflight{r: r, p: p}
177		if err := pf.checkContext(ctx); err != nil {
178			return res, err
179		}
180		if err := pf.checkReachable(ctx); err != nil {
181			return res, err
182		}
183		for _, perm := range permissionsByOp[op] {
184			if err := pf.checkPermission(ctx, perm); err != nil {
185				return res, err
186			}
187		}
188		res, err := pf.checkNamespace(ctx, op)
189		if err != nil {
190			return res, err
191		}
192		if op == OpUp {
193			if err := pf.checkNodePorts(ctx); err != nil {
194				return res, err
195			}
196		}
197		// The operations that reach the registries through a port-forward on the
198		// loopback have no use for the node address, and no can-i question covers
199		// get nodes.
200		if op.readsNode() {
201			if res.NodeIP, err = pf.nodeIP(ctx); err != nil {
202				return res, err
203			}
204		}
205		return res, nil
206	}
207	
208	type preflight struct {
209		r Runner
210		p Params
211	}
212	
213	// local runs a call that does not reach the API server.
214	func (pf preflight) local(ctx context.Context, args ...string) (stdout, stderr string, err error) {
215		out, errOut, err := pf.r.Run(ctx, nil, args...)
216		return string(out), string(errOut), err
217	}
218	
219	// remote runs a call that reaches the API server, under a request timeout.
220	func (pf preflight) remote(ctx context.Context, args ...string) (stdout, stderr string, err error) {
221		return pf.local(ctx, slices.Concat(args, []string{requestTimeout})...)
222	}
223	
224	// command is the kubectl command line a user can run to repeat a call.
225	func (pf preflight) command(args ...string) string {
226		return "kubectl --context " + pf.p.Context + " " + strings.Join(args, " ")
227	}
228	
229	// failure turns a failed kubectl call into a BenchError whose kind comes from
230	// the stderr. Neither the stderr nor the sub-process error reaches the message.
231	func (pf preflight) failure(what string, args []string, stderr string, err error) *BenchError {
232		kind := classifyKubectl(stderr)
233		reason := "kubectl failed"
234		switch kind {
235		case Forbidden:
236			reason = "the API server refused the request (forbidden)"
237		case ClusterUnreachable:
238			reason = "the cluster did not answer"
239		}
240		return &BenchError{
241			Kind:  kind,
242			Cause: "could not " + what + ": " + reason,
243			Check: pf.command(args...),
244			Err:   err,
245		}
246	}
247	
248	func (pf preflight) checkContext(ctx context.Context) error {
249		args := []string{"config", "get-contexts", "-o", "name"}
250		out, errOut, err := pf.local(ctx, args...)
251		if err != nil {
252			return pf.failure("list the kubeconfig contexts", args, errOut, err)
253		}
254		for _, line := range strings.Split(out, "\n") {
255			if strings.TrimSpace(line) == pf.p.Context {
256				return nil
257			}
258		}
259		return &BenchError{
260			Kind:  ContextNotFound,
261			Cause: fmt.Sprintf("no kubeconfig context is named %q", pf.p.Context),
262			Check: "kubectl config get-contexts -o name, then set NEXUS_BENCH_CONTEXT to one of them",
263		}
264	}
265	
266	func (pf preflight) checkReachable(ctx context.Context) error {
267		args := []string{"get", "--raw", "/readyz"}
268		_, errOut, err := pf.remote(ctx, args...)
269		if err == nil {
270			return nil
271		}
272		// A refusal (an expired token, a 403) is not an absent cluster: say so.
273		// Anything else, classified or not, means the server did not answer.
274		if classifyKubectl(errOut) == Forbidden {
275			return pf.failure("reach the API server", args, errOut, err)
276		}
277		return &BenchError{
278			Kind:  ClusterUnreachable,
279			Cause: fmt.Sprintf("the API server of context %q does not answer /readyz", pf.p.Context),
280			Check: pf.command(args...),
281			Err:   err,
282		}
283	}
284	
285	// checkPermission asks "kubectl auth can-i". A "no" arrives on stdout with a
286	// non-zero exit, so the answer is read before the error.
287	func (pf preflight) checkPermission(ctx context.Context, perm permission) error {
288		args := []string{"auth", "can-i", perm.verb, perm.resource}
289		if perm.subresource != "" {
290			args = append(args, "--subresource="+perm.subresource)
291		}
292		where := "cluster-wide"
293		switch perm.scope {
294		case scopeNamespace:
295			args = append(args, "-n", pf.p.Namespace)
296			where = fmt.Sprintf("in namespace %q", pf.p.Namespace)
297		case scopeAll:
298			args = append(args, "-A")
299			where = "in all namespaces"
300		}
301		out, errOut, err := pf.remote(ctx, args...)
302		answer := strings.TrimSpace(out)
303		switch {
304		case strings.HasPrefix(answer, "no"):
305			return &BenchError{
306				Kind:  Forbidden,
307				Cause: fmt.Sprintf("the current user is not allowed to %s %s %s", perm.verb, perm.name(), where),
308				Check: pf.command(args...),
309				Err:   err,
310			}
311		case err == nil && strings.HasPrefix(answer, "yes"):
312			return nil
313		}
314		return pf.failure(fmt.Sprintf("check the permission to %s %s", perm.verb, perm.name()), args, errOut, err)
315	}
316	
317	// namespaceObject is the part of a Namespace the preflight reads.
318	type namespaceObject struct {
319		Metadata struct {
320			Labels map[string]string `json:"labels"`
321		} `json:"metadata"`
322	}
323	
324	func (pf preflight) checkNamespace(ctx context.Context, op Op) (PreflightResult, error) {
325		var res PreflightResult
326		ns := pf.p.Namespace
327		args := []string{"get", "namespace", ns, "-o", "json"}
328		out, errOut, err := pf.remote(ctx, args...)
329		switch {
330		case err != nil && isNotFound(errOut):
331			// Absent is fine for up and down only.
332			if op != OpUp && op != OpDown {
333				return res, &BenchError{
334					Kind:  NamespaceMissing,
335					Cause: fmt.Sprintf("namespace %q does not exist", ns),
336					Check: pf.command(args[:3]...) + ", then run `mise run nexus-bench:up`",
337					Err:   err,
338				}
339			}
340			return res, nil
341		case err != nil:
342			return res, pf.failure(fmt.Sprintf("read the namespace %q", ns), args, errOut, err)
343		}
344	
345		var obj namespaceObject
346		if err := json.Unmarshal([]byte(out), &obj); err != nil {
347			return res, &BenchError{
348				Kind:  Unclassified,
349				Cause: fmt.Sprintf("kubectl answered with something that is not a Namespace for %q", ns),
350				Check: pf.command(args...),
351				Err:   err,
352			}
353		}
354		res.NamespaceExists = true
355		res.NamespaceOurs = obj.Metadata.Labels[managedByLabel] == managedByValue
356		if !res.NamespaceOurs {
357			return res, &BenchError{
358				Kind:  NamespaceForeign,
359				Cause: fmt.Sprintf("namespace %q exists but does not carry the label %s=%s, so the bench did not create it", ns, managedByLabel, managedByValue),
360				Check: pf.command("get", "namespace", ns, "--show-labels") + ", or choose another NEXUS_BENCH_NAMESPACE",
361			}
362		}
363		return res, nil
364	}
365	
366	// serviceList is the part of a Service list the preflight reads.
367	type serviceList struct {
368		Items []struct {
369			Metadata struct {
370				Name      string `json:"name"`
371				Namespace string `json:"namespace"`
372			} `json:"metadata"`
373			Spec struct {
374				Ports []struct {
375					NodePort int `json:"nodePort"`
376				} `json:"ports"`
377			} `json:"spec"`
378		} `json:"items"`
379	}
380	
381	// checkNodePorts reads every Service of the cluster: the list of taken
382	// NodePorts is not a constant (F1). Our own Service, in our namespace, may hold
383	// them: that is a second up.
384	func (pf preflight) checkNodePorts(ctx context.Context) error {
385		args := []string{"get", "services", "-A", "-o", "json"}
386		out, errOut, err := pf.remote(ctx, args...)
387		if err != nil {
388			return pf.failure("list the Services of the cluster", args, errOut, err)
389		}
390		var list serviceList
391		if err := json.Unmarshal([]byte(out), &list); err != nil {
392			return &BenchError{
393				Kind:  Unclassified,
394				Cause: "kubectl answered with something that is not a Service list",
395				Check: pf.command(args...),
396				Err:   err,
397			}
398		}
399		var taken []string
400		for _, svc := range list.Items {
401			if svc.Metadata.Namespace == pf.p.Namespace && svc.Metadata.Name == nexusServiceName {
402				continue
403			}
404			for _, port := range svc.Spec.Ports {
405				if port.NodePort == pf.p.HTTPNodePort || port.NodePort == pf.p.DockerNodePort {
406					taken = append(taken, fmt.Sprintf("%d is held by Service %s/%s", port.NodePort, svc.Metadata.Namespace, svc.Metadata.Name))
407				}
408			}
409		}
410		if len(taken) > 0 {
411			return &BenchError{
412				Kind:  NodePortTaken,
413				Cause: "NodePort " + strings.Join(taken, ", "),
414				Check: pf.command(args...) + ", then set NEXUS_BENCH_HTTP_NODEPORT and NEXUS_BENCH_DOCKER_NODEPORT to free ports",
415			}
416		}
417		return nil
418	}
419	
420	// nodeList is the part of a Node list the preflight reads.
421	type nodeList struct {
422		Items []struct {
423			Status struct {
424				Addresses []struct {
425					Type    string `json:"type"`
426					Address string `json:"address"`
427				} `json:"addresses"`
428			} `json:"status"`
429		} `json:"items"`
430	}
431	
432	// nodeIP returns the first InternalIP any node reports, or "" when none does.
433	func (pf preflight) nodeIP(ctx context.Context) (string, error) {
434		args := []string{"get", "nodes", "-o", "json"}
435		out, errOut, err := pf.remote(ctx, args...)
436		if err != nil {
